uint64_t scriptUnsigned64(const Json& value,uint64_t fallback,const char* label){
    if(value.isNull())return fallback;
    if(value.isString()){
        const auto& text=value.asString(); uint64_t parsed=0;
        const auto result=std::from_chars(text.data(),text.data()+text.size(),parsed,10);
        if(text.empty()||result.ec!=std::errc{}||result.ptr!=text.data()+text.size())throw std::runtime_error(std::string(label)+" must be an unsigned 64-bit integer or a decimal string");
        return parsed;
    }
    if(value.isNumber()){
        const double number=value.asNumber();
        constexpr double maxExactInteger=9007199254740991.0;
        if(!std::isfinite(number)||number<0||std::floor(number)!=number||number>maxExactInteger)throw std::runtime_error(std::string(label)+" numeric form must be an integer from 0 to 9007199254740991; use a decimal string for larger seeds");
        return (uint64_t)number;
    }
    throw std::runtime_error(std::string(label)+" must be an unsigned 64-bit integer or a decimal string");
}
uint32_t scriptUnsigned32(const Json& value,uint32_t fallback,const char* label){
    const uint64_t parsed=scriptUnsigned64(value,fallback,label);
    if(parsed>std::numeric_limits<uint32_t>::max())throw std::runtime_error(std::string(label)+" must be an unsigned 32-bit integer from 0 to 4294967295");
    return (uint32_t)parsed;
}
