void ScriptScene3D::addCrowd(ScriptCrowd* simulation,const std::string& group,const std::string& lookFunction,const std::string& style,uint64_t seed,int faces,int fps){
if(!simulation||!simulation->value||group.empty()||fps<1||fps>240||faces<0||faces>256||lookFunction.size()>128)throw std::runtime_error("addCrowd needs a simulation, group, fps 1..240, faces 0..256 and callback name up to 128 characters");
const int first=simulation->value->first(group);const auto& world=simulation->value->world();int count=0;for(const auto& g:world.groups)if(g.name==group){count=g.count;break;}if(count<1)throw std::runtime_error("addCrowd group has no agents");
std::function<rig::Look(int)> makeLook;
if(!lookFunction.empty()){auto& call=invocation();if(!call.drawing||!call.splatSampleFunction)throw std::runtime_error("addCrowd lookFunction is only available while drawing a composition");const auto dispatch=call.splatSampleFunction;makeLook=[dispatch,lookFunction](int i){const auto encoded=dispatch(lookFunction,i);if(encoded.size()>256*1024)throw std::runtime_error("crowd look callback result exceeds 256 KiB");const auto desc=Json::parse(encoded);if(!desc.isObject())throw std::runtime_error("crowd look callback must return a rig look JSON object");return scriptLook(desc);};}
else if(style=="person")makeLook=[seed](int i){return crowd::person(i,(unsigned)seed);};else if(style=="zombie")makeLook=[seed](int i){return crowd::zombie(i,(unsigned)seed);};else if(style=="herd")makeLook=[seed,group](int i){return crowd::herd(group,i,(unsigned)seed);};else throw std::runtime_error("addCrowd style must be person, zombie or herd when lookFunction is empty");
auto characters=crowd::cast(simulation->value,group,makeLook,faces);for(int i=0;i<count;++i)crowd::add(*value,simulation->value,first+i,characters[(size_t)i],fps);
}
