void scriptG3dLookRotation(float fx,float fy,float fz,float ux,float uy,float uz,CScriptArray* out){
    const float input[]={fx,fy,fz,ux,uy,uz};
    if(!out||out->GetElementTypeId()!=asTYPEID_FLOAT)throw std::runtime_error("g3d::lookRotation output must be array<float>");
    for(float v:input)if(!std::isfinite(v))throw std::runtime_error("g3d::lookRotation vectors must be finite");
    const Vector3 result=g3d::lookRotation({fx,fy,fz},{ux,uy,uz});
    const float values[]={result.x,result.y,result.z};
    out->Resize(3);
    for(asUINT i=0;i<3;++i)out->SetValue(i,const_cast<float*>(&values[i]));
}
