std::string scriptDiagramFontSample(const dg::Graph& graph) {
    std::string sample;
    auto append=[&](const std::string& text) { if(sample.size()+text.size()>4u*1024u*1024u)throw std::runtime_error("diagram font sample exceeds 4 MiB"); sample+=text; sample.push_back('\n'); };
    append(graph.title); for(const auto& node:graph.nodes)append(node.label); for(const auto& edge:graph.edges)append(edge.label); for(const auto& group:graph.groups)append(group.label);
    return sample;
}
