void scriptApplyDiagramStyle(dg::Style& style,const Json& value) {
    if(!value.isObject())throw std::runtime_error("diagram element style must be a JSON object");
    auto color=[&](const char* key,std::optional<Color>& field,Color fallback) { if(!value.has(key))return; const auto& item=value[key]; if(item.isNull())field.reset(); else field=value.color(key,fallback); };
    color("fill",style.fill,WHITE); color("stroke",style.stroke,WHITE); color("text",style.text,WHITE);
    if(value.has("strokeWidth")) { const auto& item=value["strokeWidth"]; if(item.isNull())style.strokeWidth.reset(); else { const double width=item.asNumber(); if(!std::isfinite(width)||width<0||width>1000)throw std::runtime_error("diagram style strokeWidth must be finite and within 0..1000"); style.strokeWidth=(float)width; } }
    if(value.has("dash")) { const auto& item=value["dash"]; if(item.isNull())style.dash.reset(); else if(item.isString()) { const auto dash=item.asString(); if(dash=="solid")style.dash=dg::Stroke::Solid; else if(dash=="dashed")style.dash=dg::Stroke::Dashed; else if(dash=="dotted")style.dash=dg::Stroke::Dotted; else throw std::runtime_error("diagram style dash must be solid, dashed, dotted or null"); } else { const double number=item.asNumber(); if(!std::isfinite(number)||number!=std::floor(number)||number<0||number>(int)dg::Stroke::Dotted)throw std::runtime_error("diagram style dash enum is out of range"); style.dash=(dg::Stroke)(int)number; } }
}
