void mediaEditAudioCue(int index,const std::string& optionsJson){
    auto& call=invocation();
    if(!call.description||call.drawing)throw std::runtime_error("media::editAudioCue is only available in configure()");
    if(optionsJson.size()>65536)throw std::runtime_error("media audio cue options exceed 64 KiB");
    const Json options=Json::parse(optionsJson);
    if(!options.isObject())throw std::runtime_error("media::editAudioCue expects a JSON object");
    auto& cues=call.description->media;
    if(index<0||index>=(int)cues.size())throw std::runtime_error("media::editAudioCue index is out of range");
    auto& cue=cues[(size_t)index];
    if(cue.kind!=MediaCue::Kind::Audio)throw std::runtime_error("media::editAudioCue cannot edit a video cue");
    for(const auto& item:options.asObject()){
        if(item.first!="file"&&item.first!="startFrom"&&item.first!="endAt"&&item.first!="playbackRate"&&item.first!="loop"&&item.first!="volume"&&item.first!="volumeFunction"&&item.first!="volumeKeys")throw std::runtime_error("unknown media audio cue option: "+item.first);
    }
    if(options.has("file")){if(!options["file"].isString()||options["file"].asString().empty())throw std::runtime_error("media audio cue file must be a nonempty string");cue.file=options["file"].asString();}
    auto number=[&](const char* key,double& target){if(!options.has(key))return;if(!options[key].isNumber()||!std::isfinite(options[key].asNumber()))throw std::runtime_error(std::string("media audio cue ")+key+" must be finite");target=options[key].asNumber();};
    number("startFrom",cue.startFrom);number("endAt",cue.endAt);number("playbackRate",cue.playbackRate);
    if(cue.playbackRate<=0)throw std::runtime_error("media audio cue playbackRate must be positive");
    if(options.has("loop")){if(!options["loop"].isBool())throw std::runtime_error("media audio cue loop must be boolean");cue.loop=options["loop"].asBool();}
    if(options.has("volume")){if(!options["volume"].isNumber()||!std::isfinite(options["volume"].asNumber())||!std::isfinite((float)options["volume"].asNumber()))throw std::runtime_error("media audio cue volume must fit a finite float");cue.volume=(float)options["volume"].asNumber();}
    if(options.has("volumeFunction")&&options.has("volumeKeys"))throw std::runtime_error("media audio cue volumeFunction and volumeKeys are mutually exclusive");
    if(options.has("volumeFunction")){if(!options["volumeFunction"].isString()||options["volumeFunction"].asString().size()>128)throw std::runtime_error("media audio cue volumeFunction must be a string of at most 128 characters");cue.volumeFunction=options["volumeFunction"].asString();cue.volumeKeys.clear();}
    if(options.has("volumeKeys")){const auto& keys=options["volumeKeys"];if(!keys.isArray()||keys.size()<4||keys.size()%2||keys.size()>2048)throw std::runtime_error("media audio cue volumeKeys needs 2..1024 frame/gain pairs");std::vector<float> parsed;parsed.reserve(keys.size());for(const auto& key:keys.asArray()){if(!key.isNumber()||!std::isfinite(key.asNumber())||!std::isfinite((float)key.asNumber()))throw std::runtime_error("media audio cue volumeKeys values must fit finite floats");parsed.push_back((float)key.asNumber());}cue.volumeKeys=std::move(parsed);cue.volumeFunction.clear();}
}
