// ---- 2D map helpers (rmtn/geomap.hpp): geo::base, choropleth, highlight, markers, labels,
// route, fly and focus. Styles are JSON objects whose keys are the C++ style fields.
const Ctx& geoMapContext(const char* what) {
    auto& call = invocation();
    if (!call.drawing) throw std::runtime_error(std::string("geo::") + what + " is only available inside draw callbacks");
    return call.context;
}
geo::Projection& geoMapProjection(ScriptGeoProjection* p, const char* what) {
    if (!p) throw std::runtime_error(std::string("geo::") + what + " needs a projection");
    return p->value;
}
float geoMapProgress(float progress, const char* what) {
    if (!std::isfinite(progress)) throw std::runtime_error(std::string("geo::") + what + " progress must be finite");
    return std::clamp(progress, 0.0f, 1.0f);
}
Json geoMapStyle(const std::string& styleJson, const char* what) {
    if (styleJson.size() > 65536) throw std::runtime_error(std::string("geo::") + what + " style exceeds 64 KiB");
    Json j = Json::parse(styleJson);
    if (!j.isObject()) throw std::runtime_error(std::string("geo::") + what + " style must be a JSON object");
    return j;
}
float geoMapSize(const Json& j, const char* key, float fallback, float limit = 4096) {
    const double v = j.num(key, fallback);
    if (!std::isfinite(v) || v < 0 || v > limit) throw std::runtime_error(std::string("geo style ") + key + " is out of range");
    return (float)v;
}
// "colors": ["#0b1d3a", "#ffd166"] as evenly spaced stops; else colorFunction / colorFunctionRgba.
void geoMapScale(geo::Scale& scale, const Json& j, const char* what) {
    scale.min = j.num("min", scale.min);
    scale.max = j.num("max", scale.max);
    if (!std::isfinite(scale.min) || !std::isfinite(scale.max) || scale.max < scale.min)
        throw std::runtime_error(std::string("geo::") + what + " scale needs finite min <= max");
    const Json& stops = j["colors"];
    if (stops.isArray()) {
        if (j.has("colorFunction") || j.has("colorFunctionRgba"))
            throw std::runtime_error(std::string("geo::") + what + " colors and color callbacks are mutually exclusive");
        if (stops.size() < 2 || stops.size() > 64) throw std::runtime_error(std::string("geo::") + what + " colors needs 2..64 stops");
        std::vector<Color> colors;
        for (const Json& stop : stops.asArray()) {
            if (!stop.isString()) throw std::runtime_error(std::string("geo::") + what + " colors must be strings like \"#rrggbb\"");
            colors.push_back(parseColor(stop.asString()));
        }
        scale.colors = [colors](float t) {
            const float x = std::clamp(t, 0.0f, 1.0f) * (float)(colors.size() - 1);
            const size_t i = std::min((size_t)x, colors.size() - 2);
            return mixC(colors[i], colors[i + 1], x - (float)i);
        };
        return;
    }
    configurePlotColorFunction(scale.colors, j, what);
}
geo::Values geoMapValues(const std::string& valuesJson, const char* what) {
    if (valuesJson.size() > 1024 * 1024) throw std::runtime_error(std::string("geo::") + what + " values exceed 1 MiB");
    const Json j = Json::parse(valuesJson);
    if (!j.isObject()) throw std::runtime_error(std::string("geo::") + what + " values must be a JSON object of code: number");
    geo::Values out;
    for (const auto& [key, value] : j.asObject()) {
        if (!value.isNumber() || !std::isfinite(value.asNumber()))
            throw std::runtime_error(std::string("geo::") + what + " value for " + key + " must be a finite number");
        out.push_back({ key, value.asNumber() });
    }
    return out;
}
std::vector<geo::LonLat> geoMapStops(CScriptArray* pairs, const char* what) {
    const auto values = geoCoordinateValues(pairs, 20000);
    if (values.size() < 2 || values.size() % 2) throw std::runtime_error(std::string("geo::") + what + " needs lon/lat pairs");
    std::vector<geo::LonLat> out;
    for (size_t i = 0; i < values.size(); i += 2) {
        validateGeoCoordinatePair(values[i], values[i + 1]);
        out.push_back({ values[i], values[i + 1] });
    }
    return out;
}
geo::LonLat geoMapItemAt(const Json& item, const char* what) {
    if (!item.isObject() || !item["lon"].isNumber() || !item["lat"].isNumber())
        throw std::runtime_error(std::string("geo::") + what + " items need numeric lon and lat");
    const double lon = item["lon"].asNumber(), lat = item["lat"].asNumber();
    validateGeoCoordinatePair(lon, lat);
    return { lon, lat };
}
Json geoMapItems(const std::string& itemsJson, const char* what) {
    if (itemsJson.size() > 1024 * 1024) throw std::runtime_error(std::string("geo::") + what + " items exceed 1 MiB");
    Json items = Json::parse(itemsJson);
    if (!items.isArray() || items.size() > 4000) throw std::runtime_error(std::string("geo::") + what + " expects an array of up to 4000 items");
    return items;
}
std::string geoMapJsonString(const std::string& s) { return Json(s).dump(); }

ScriptGeoLayer* geoBundledLayer(const std::string& name) {
    auto* out = new ScriptGeoLayer();
    try { out->value = geoLayer(name); } catch (...) { delete out; throw; }
    return out;
}
ScriptGeoProjection* geoFlyProjections(ScriptGeoProjection* a, ScriptGeoProjection* b, double t, double zoomOut) {
    if (!a || !b) throw std::runtime_error("geo::fly needs two projections");
    if (!std::isfinite(t) || !std::isfinite(zoomOut) || zoomOut < 0 || zoomOut > 64)
        throw std::runtime_error("geo::fly needs finite progress and zoomOut 0..64");
    auto* p = new ScriptGeoProjection();
    p->value = geo::Projection::fly(a->value, b->value, t, zoomOut);
    return p;
}
ScriptGeoProjection* geoFocusProjection(ScriptGeoProjection* base, ScriptGeoGeometry* g, float x, float y, float w, float h, float padding) {
    if (!base || !g) throw std::runtime_error("geo::focus needs a projection and a geometry");
    if (!std::isfinite(x) || !std::isfinite(y) || !std::isfinite(w) || !std::isfinite(h) || w <= 0 || h <= 0 || !std::isfinite(padding) || padding < 0 ||
        padding * 2 >= std::min(w, h))
        throw std::runtime_error("geo::focus needs a finite positive box and a padding smaller than half of it");
    auto* p = new ScriptGeoProjection();
    p->value = geo::focus(base->value, { x, y, w, h }, g->value, padding);
    return p;
}

void geoDrawBase(ScriptGeoProjection* map, float progress, const std::string& styleJson) {
    const Ctx& c = geoMapContext("base");
    const Json j = geoMapStyle(styleJson, "base");
    geo::BaseStyle s;
    s.ocean = j.color("ocean", s.ocean); s.land = j.color("land", s.land); s.coast = j.color("coast", s.coast);
    s.border = j.color("border", s.border); s.graticule = j.color("graticule", s.graticule);
    s.coastWidth = geoMapSize(j, "coastWidth", s.coastWidth, 64); s.borderWidth = geoMapSize(j, "borderWidth", s.borderWidth, 64);
    s.graticuleWidth = geoMapSize(j, "graticuleWidth", s.graticuleWidth, 64);
    s.graticuleStep = j.num("graticuleStep", s.graticuleStep);
    if (!std::isfinite(s.graticuleStep) || s.graticuleStep < 0 || s.graticuleStep > 180) throw std::runtime_error("geo::base graticuleStep must be 0..180");
    geo::base(c, geoMapProjection(map, "base"), s, geoMapProgress(progress, "base"));
}
void geoDrawChoropleth(ScriptGeoProjection* map, const std::string& valuesJson, float progress, const std::string& styleJson, ScriptGeoLayer* layer) {
    const Ctx& c = geoMapContext("choropleth");
    const Json j = geoMapStyle(styleJson, "choropleth");
    geo::ChoroplethStyle s;
    geoMapScale(s.scale, j, "choropleth");
    s.missing = j.color("missing", s.missing); s.border = j.color("border", s.border);
    s.borderWidth = geoMapSize(j, "borderWidth", s.borderWidth, 64); s.stagger = geoMapSize(j, "stagger", s.stagger, 1);
    geo::choropleth(c, geoMapProjection(map, "choropleth"), geoMapValues(valuesJson, "choropleth"), s, geoMapProgress(progress, "choropleth"),
                    layer ? layer->value : geo::countries());
}
void geoDrawColorbar(float x, float y, float w, float h, const std::string& valuesJson, float progress, const std::string& styleJson) {
    const Ctx& c = geoMapContext("colorbar");
    if (!std::isfinite(x) || !std::isfinite(y) || !std::isfinite(w) || !std::isfinite(h) || w <= 0 || h <= 0)
        throw std::runtime_error("geo::colorbar needs a finite positive box");
    const Json j = geoMapStyle(styleJson, "colorbar");
    geo::Scale scale;
    geoMapScale(scale, j, "colorbar");
    plot::ColorbarStyle s;
    s.title = j.str("title", s.title); s.decimals = j.integer("decimals", s.decimals); s.suffix = j.str("suffix", s.suffix);
    s.textSize = geoMapSize(j, "textSize", s.textSize, 512); s.textColor = j.color("textColor", s.textColor);
    geo::colorbar(c, { x, y, w, h }, scale.over(geoMapValues(valuesJson, "colorbar")), s, geoMapProgress(progress, "colorbar"));
}
void geoDrawHighlight(ScriptGeoProjection* map, ScriptGeoGeometry* region, float progress, const std::string& styleJson) {
    const Ctx& c = geoMapContext("highlight");
    if (!region) throw std::runtime_error("geo::highlight needs a geometry");
    const Json j = geoMapStyle(styleJson, "highlight");
    geo::HighlightStyle s;
    s.fill = j.color("fill", s.fill); s.stroke = j.color("stroke", s.stroke); s.dim = j.color("dim", s.dim);
    s.width = geoMapSize(j, "width", s.width, 64);
    geo::highlight(c, geoMapProjection(map, "highlight"), region->value, s, geoMapProgress(progress, "highlight"));
}
void geoDrawMarkers(ScriptGeoProjection* map, const std::string& itemsJson, float progress, const std::string& styleJson) {
    const Ctx& c = geoMapContext("markers");
    const Json items = geoMapItems(itemsJson, "markers"), j = geoMapStyle(styleJson, "markers");
    std::vector<geo::Marker> data;
    data.reserve(items.size());
    for (const Json& item : items.asArray()) {
        geo::Marker m;
        m.at = geoMapItemAt(item, "markers");
        m.label = item.str("label", "");
        m.value = item.num("value", 1);
        if (m.label.size() > 512 || !std::isfinite(m.value)) throw std::runtime_error("geo::markers items need labels up to 512 bytes and finite values");
        m.color = item.color("color", m.color);
        data.push_back(std::move(m));
    }
    geo::MarkerStyle s;
    s.radius = geoMapSize(j, "radius", s.radius, 512); s.sized = j.flag("sized", s.sized);
    s.color = j.color("color", s.color); s.ring = j.color("ring", s.ring); s.ringWidth = geoMapSize(j, "ringWidth", s.ringWidth, 64);
    s.stagger = geoMapSize(j, "stagger", s.stagger, 1); s.labels = j.flag("labels", s.labels);
    s.textSize = geoMapSize(j, "textSize", s.textSize, 512); s.textColor = j.color("textColor", s.textColor);
    s.halo = j.color("halo", s.halo); s.bold = j.flag("bold", s.bold);
    if (s.textSize <= 0) throw std::runtime_error("geo::markers textSize must be positive");
    geo::markers(c, geoMapProjection(map, "markers"), data, s, geoMapProgress(progress, "markers"));
}
void geoDrawLabels(ScriptGeoProjection* map, const std::string& itemsJson, float progress, const std::string& styleJson) {
    const Ctx& c = geoMapContext("labels");
    const Json items = geoMapItems(itemsJson, "labels"), j = geoMapStyle(styleJson, "labels");
    std::vector<geo::Label> data;
    data.reserve(items.size());
    for (const Json& item : items.asArray()) {
        geo::Label l{ geoMapItemAt(item, "labels"), item.str("text", "") };
        if (l.text.size() > 512) throw std::runtime_error("geo::labels text is limited to 512 bytes");
        data.push_back(std::move(l));
    }
    geo::LabelStyle s;
    s.size = geoMapSize(j, "size", s.size, 512); s.color = j.color("color", s.color); s.halo = j.color("halo", s.halo);
    s.bold = j.flag("bold", s.bold); s.offset = geoMapSize(j, "offset", s.offset, 512); s.margin = geoMapSize(j, "margin", s.margin, 512);
    s.stagger = geoMapSize(j, "stagger", s.stagger, 1);
    if (s.size <= 0) throw std::runtime_error("geo::labels size must be positive");
    geo::labels(c, geoMapProjection(map, "labels"), data, s, geoMapProgress(progress, "labels"));
}
std::string geoPlacesJson(ScriptGeoLayer* layer, int limit, const std::string& valueProperty) {
    if (!layer || limit < 0 || limit > 4000) throw std::runtime_error("geo::places needs a layer and a limit of 0..4000");
    std::string out = "[";
    for (const geo::Marker& m : geo::places(layer->value, limit ? (size_t)limit : 4000, valueProperty)) {
        if (out.size() > 1) out += ",";
        out += "{\"lon\":" + Json(m.at.lon).dump() + ",\"lat\":" + Json(m.at.lat).dump() + ",\"label\":" + geoMapJsonString(m.label) +
               ",\"value\":" + Json(std::isfinite(m.value) ? m.value : 1.0).dump() + "}";
    }
    return out + "]";
}
std::string geoNamesJson(ScriptGeoLayer* layer, int limit) {
    if (!layer || limit < 0 || limit > 4000) throw std::runtime_error("geo::names needs a layer and a limit of 0..4000");
    std::string out = "[";
    for (const geo::Label& l : geo::names(layer->value, limit ? (size_t)limit : 4000)) {
        if (out.size() > 1) out += ",";
        out += "{\"lon\":" + Json(l.at.lon).dump() + ",\"lat\":" + Json(l.at.lat).dump() + ",\"text\":" + geoMapJsonString(l.text) + "}";
    }
    return out + "]";
}
void geoDrawRoute(ScriptGeoProjection* map, CScriptArray* pairs, float progress, const std::string& styleJson) {
    const Ctx& c = geoMapContext("route");
    const Json j = geoMapStyle(styleJson, "route");
    geo::RouteStyle s;
    s.color = j.color("color", s.color); s.ghost = j.color("ghost", s.ghost); s.headColor = j.color("headColor", s.headColor);
    s.width = geoMapSize(j, "width", s.width, 256); s.head = geoMapSize(j, "head", s.head, 256); s.stops = geoMapSize(j, "stops", s.stops, 256);
    s.tail = geoMapSize(j, "tail", s.tail, 1); s.arrow = j.flag("arrow", s.arrow);
    if (j["dash"].isArray()) {
        if (j["dash"].size() > 16) throw std::runtime_error("geo::route dash takes up to 16 lengths");
        for (const Json& d : j["dash"].asArray()) {
            if (!d.isNumber() || !std::isfinite(d.asNumber()) || d.asNumber() <= 0 || d.asNumber() > 4096)
                throw std::runtime_error("geo::route dash lengths must be positive numbers");
            s.dash.push_back((float)d.asNumber());
        }
    }
    geo::route(c, geoMapProjection(map, "route"), geoMapStops(pairs, "route"), s, geoMapProgress(progress, "route"));
}
ScriptPath* geoRoutePath(ScriptGeoProjection* map, CScriptArray* pairs, double from, double to) {
    if (!std::isfinite(from) || !std::isfinite(to)) throw std::runtime_error("geo::routePath needs finite fractions");
    auto* out = new ScriptPath();
    try { out->value = geo::route(geoMapProjection(map, "routePath"), geoMapStops(pairs, "routePath"), from, to); } catch (...) { delete out; throw; }
    return out;
}
void geoAlong(CScriptArray* pairs, double progress, CScriptArray* out) {
    if (!std::isfinite(progress) || !out || out->GetElementTypeId() != asTYPEID_DOUBLE)
        throw std::runtime_error("geo::along needs finite progress and an array<double> output");
    double heading = 0;
    const geo::LonLat p = geo::along(geoMapStops(pairs, "along"), progress, &heading);
    double v[] = { p.lon, p.lat, heading };
    out->Resize(3);
    for (asUINT i = 0; i < 3; ++i) out->SetValue(i, &v[i]);
}
double geoRouteLength(CScriptArray* pairs) { return geo::length(geoMapStops(pairs, "length")); }
// A table of code x time ("code,2000,2010\nIDN,214,244") to the values at one time, as the
// JSON object geo::choropleth takes. The parsed table is cached per text.
std::string geoValuesAt(const std::string& csv, double time) {
    if (csv.size() > 1024 * 1024 || !std::isfinite(time)) throw std::runtime_error("geo::valuesAt needs CSV text up to 1 MiB and a finite time");
    static thread_local std::unordered_map<std::string, geo::Series> cache;
    auto it = cache.find(csv);
    if (it == cache.end()) {
        if (cache.size() >= 8) cache.clear();
        it = cache.emplace(csv, geo::Series::from(plot::Table::parseCsv(csv))).first;
    }
    std::string out = "{";
    for (const auto& [key, value] : it->second.at(time)) {
        if (out.size() > 1) out += ",";
        out += geoMapJsonString(key) + ":" + Json(std::isfinite(value) ? value : 0.0).dump();
    }
    return out + "}";
}

void registerGeoMap(asIScriptEngine* e) {   // called with the "geo" namespace active
    check(e->RegisterGlobalFunction("GeoLayer@ layer(const string &in name)", asFUNCTION(geoBundledLayer), asCALL_CDECL));
    check(e->RegisterGlobalFunction("GeoProjection@ fly(GeoProjection@ a, GeoProjection@ b, double progress, double zoomOut = 0)", asFUNCTION(geoFlyProjections), asCALL_CDECL));
    check(e->RegisterGlobalFunction("GeoProjection@ focus(GeoProjection@ base, GeoGeometry@ geometry, float x, float y, float w, float h, float padding = 0)", asFUNCTION(geoFocusProjection), asCALL_CDECL));
    check(e->RegisterGlobalFunction("void base(GeoProjection@ map, float progress = 1, const string &in styleJson = \"{}\")", asFUNCTION(geoDrawBase), asCALL_CDECL));
    check(e->RegisterGlobalFunction("void choropleth(GeoProjection@ map, const string &in valuesJson, float progress = 1, const string &in styleJson = \"{}\", GeoLayer@ layer = null)", asFUNCTION(geoDrawChoropleth), asCALL_CDECL));
    check(e->RegisterGlobalFunction("void colorbar(float x, float y, float width, float height, const string &in valuesJson, float progress = 1, const string &in styleJson = \"{}\")", asFUNCTION(geoDrawColorbar), asCALL_CDECL));
    check(e->RegisterGlobalFunction("void highlight(GeoProjection@ map, GeoGeometry@ region, float progress = 1, const string &in styleJson = \"{}\")", asFUNCTION(geoDrawHighlight), asCALL_CDECL));
    check(e->RegisterGlobalFunction("void markers(GeoProjection@ map, const string &in itemsJson, float progress = 1, const string &in styleJson = \"{}\")", asFUNCTION(geoDrawMarkers), asCALL_CDECL));
    check(e->RegisterGlobalFunction("void labels(GeoProjection@ map, const string &in itemsJson, float progress = 1, const string &in styleJson = \"{}\")", asFUNCTION(geoDrawLabels), asCALL_CDECL));
    check(e->RegisterGlobalFunction("string places(GeoLayer@ layer, int limit = 0, const string &in valueProperty = \"pop\")", asFUNCTION(geoPlacesJson), asCALL_CDECL));
    check(e->RegisterGlobalFunction("string names(GeoLayer@ layer, int limit = 0)", asFUNCTION(geoNamesJson), asCALL_CDECL));
    check(e->RegisterGlobalFunction("void route(GeoProjection@ map, const array<double> &in lonLatPairs, float progress = 1, const string &in styleJson = \"{}\")", asFUNCTION(geoDrawRoute), asCALL_CDECL));
    check(e->RegisterGlobalFunction("Path@ routePath(GeoProjection@ map, const array<double> &in lonLatPairs, double from = 0, double to = 1)", asFUNCTION(geoRoutePath), asCALL_CDECL));
    check(e->RegisterGlobalFunction("void along(const array<double> &in lonLatPairs, double progress, array<double> &out lonLatBearing)", asFUNCTION(geoAlong), asCALL_CDECL));
    check(e->RegisterGlobalFunction("double length(const array<double> &in lonLatPairs)", asFUNCTION(geoRouteLength), asCALL_CDECL));
    check(e->RegisterGlobalFunction("string valuesAt(const string &in csv, double time)", asFUNCTION(geoValuesAt), asCALL_CDECL));
}
std::shared_ptr<dg::Diagram> cachedDiagram(const std::string& source, const std::string& format,                                           const std::string& theme, int stagger, int revealDuration) {
    static thread_local std::unordered_map<std::string, std::shared_ptr<dg::Diagram>> cache; const auto key = source + "\n" + format + "\n" + theme + "\n" + std::to_string(stagger) + ":" + std::to_string(revealDuration); auto it = cache.find(key); if (it != cache.end()) return it->second; if (cache.size() >= 32) cache.clear(); auto graph = dg::parse(source, format); auto style = theme == "dark" ? dg::Theme::dark() : theme == "blueprint" ? dg::Theme::blueprint() :                 theme == "bpmn" ? dg::Theme::bpmn() : dg::Theme::light(); auto diagram = dg::Diagram::make(std::move(graph), style); diagram->build(0, std::max(1, stagger), std::max(1, revealDuration)); return cache.emplace(key, std::move(diagram)).first->second; }
dg::Graph parseScriptDiagram(const std::string& source,const std::string& format,const Json& rdfJson) {
    if(source.size()>1024*1024)throw std::runtime_error("diagram source exceeds 1 MiB"); if(format!="turtle"&&format!="ntriples"&&format!="jsonld")return dg::parse(source,format); dg::RdfOptions rdf; if(!rdfJson.isNull()){
        if(!rdfJson.isObject())throw std::runtime_error("diagram rdfOptions must be an object"); rdf.literalNodes=rdfJson.flag("literalNodes",rdf.literalNodes); rdf.typeEdges=rdfJson.flag("typeEdges",rdf.typeEdges); rdf.maxLiteralLength=rdfJson.integer("maxLiteralLength",rdf.maxLiteralLength); rdf.language=rdfJson.str("language",rdf.language); if(rdf.maxLiteralLength<0||rdf.maxLiteralLength>10000||rdf.language.size()>64)throw std::runtime_error("diagram RDF maxLiteralLength must be 0..10000 and language at most 64 characters"); }
    if(format=="jsonld")return dg::jsonld(Json::parse(source),rdf); return dg::turtle(source,rdf); }
