rig::Mount scriptRigMount(const Json& desc) {
    if(!desc.isObject()||!desc["carrier"].isObject())throw std::runtime_error("rig mount cue needs a carrier character object");
    auto carrier=cachedScriptCharacter(desc["carrier"]);
    const double from=desc.num("from",0),until=desc.num("until",1e30),blend=desc.num("blend",0.3);
    if(!std::isfinite(from)||!std::isfinite(until)||!std::isfinite(blend)||from<0||until<from||blend<0||blend>60)
        throw std::runtime_error("rig mount times must be finite and ordered; blend must be 0..60 seconds");
    rig::Mount mount;
    const auto type=desc.str("type","joint");
    if(type=="saddle")mount=rig::saddle(carrier,from,until);
    else if(type!="joint")throw std::runtime_error("rig mount type must be joint or saddle");
    else { mount.carrier=carrier; mount.from=from; mount.until=until; }
    if(desc.has("joint"))mount.joint=rig::joint(carrier->lookAt(0).build,desc.str("joint","root"));
    if(desc.has("at"))mount.at=jsonV3(desc["at"]);
    if(desc.has("rot"))mount.rot=jsonV3(desc["rot"]);
    mount.blend=blend; mount.upright=desc.flag("upright",mount.upright);
    const auto& grips=desc["grips"];
    if(!grips.isNull()) {
        if(!grips.isArray()||grips.size()>16)throw std::runtime_error("rig mount grips must be an array of at most 16 entries");
        mount.grips.clear();
        for(const auto& grip:grips.asArray()) {
            const auto limbName=grip.str("limb",""); rig::Limb limb;
            if(limbName=="handL")limb=rig::Limb::HandL; else if(limbName=="handR")limb=rig::Limb::HandR;
            else if(limbName=="footL")limb=rig::Limb::FootL; else if(limbName=="footR")limb=rig::Limb::FootR;
            else throw std::runtime_error("rig mount grip limb must be handL, handR, footL or footR");
            mount.grips.push_back({limb,rig::joint(carrier->lookAt(0).build,grip.str("joint","root")),jsonV3(grip["at"])});
        }
    }
    return mount;
}
