aud::AnalysisPtr cachedAudio(const std::string& file) {
    static thread_local std::unordered_map<std::string, aud::AnalysisPtr> cache; auto it = cache.find(file); if (it != cache.end()) return it->second; if (cache.size() >= 24) cache.clear(); return cache.emplace(file, aud::analyze(file)).first->second; }
sub::Track cachedSubtitles(const std::string& file) {
    static thread_local std::unordered_map<std::string, sub::Track> cache; auto it = cache.find(file); if (it != cache.end()) return it->second; if (cache.size() >= 24) cache.clear(); return cache.emplace(file, sub::load(file)).first->second; }
double subtitleWhen(const std::string& file,const std::string& phrase,double after) {
 return cachedSubtitles(file).when(phrase,after); }
int subtitleFrameOf(const std::string& file,const std::string& phrase,int fps,double after) {
 return cachedSubtitles(file).frameOf(phrase,fps,after); }
